<?php
declare(strict_types=1);require_once __DIR__.'/error_bootstrap.php';ini_set('session.cookie_httponly','1');ini_set('session.cookie_samesite','Strict');if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')ini_set('session.cookie_secure','1');session_start();date_default_timezone_set('Asia/Tehran');header('Cache-Control:no-store,private');
if(!file_exists(__DIR__.'/config.php')){header('Location:install.php');exit;}$c=require __DIR__.'/config.php';
try{$pdo=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);require_once __DIR__.'/schema.php';ensure_product_schema($pdo);require_once __DIR__.'/admin_auth.php';ts_admin_schema($pdo);}catch(Throwable $e){ts_log_internal($e,'SYS-101');ts_html_fail('SYS-101',503,'index.php');}
$me=ts_require_roles($pdo,['owner','manager']);function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function token(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){ts_html_fail('REQ-102',419,'index.php');}$a=(string)($_POST['action']??'');try{
 if($a==='create'){$name=trim((string)($_POST['name']??''));$phone=preg_replace('/\D+/','',(string)($_POST['phone']??''))??'';if($name==='')throw new RuntimeException('نام پیک را وارد کنید.');$access=bin2hex(random_bytes(24));$st=$pdo->prepare('INSERT INTO couriers(name,phone,access_token,active,created_at) VALUES(?,?,?,1,NOW())');$st->execute([$name,$phone?:null,$access]);$msg='پیک ساخته شد.';}
 if($a==='toggle'){$id=max(0,(int)($_POST['id']??0));$pdo->prepare('UPDATE couriers SET active=1-active,updated_at=NOW() WHERE id=?')->execute([$id]);$msg='وضعیت پیک تغییر کرد.';}
 if($a==='regen'){$id=max(0,(int)($_POST['id']??0));$pdo->prepare('UPDATE couriers SET access_token=?,updated_at=NOW() WHERE id=?')->execute([bin2hex(random_bytes(24)),$id]);$msg='لینک ورود پیک عوض شد.';}
 if($a==='assign'){$oid=max(0,(int)($_POST['order_id']??0));$cid=max(0,(int)($_POST['courier_id']??0));if(!$oid||!$cid)throw new RuntimeException('سفارش و پیک را انتخاب کنید.');$q=$pdo->prepare('SELECT id FROM couriers WHERE id=? AND active=1');$q->execute([$cid]);if(!$q->fetchColumn())throw new RuntimeException('پیک فعال نیست.');$pdo->prepare("UPDATE orders SET courier_id=?,courier_assigned_at=NOW(),status=CASE WHEN status='ready' THEN 'out' ELSE status END,status_updated_at=NOW() WHERE id=? AND status NOT IN ('delivered','cancelled')")->execute([$cid,$oid]);$msg='سفارش به پیک تحویل شد.';}
 }catch(Throwable $x){$err=ts_error_text('SYS-100');ts_log_internal($x,'SYS-100');}}
$couriers=$pdo->query('SELECT * FROM couriers ORDER BY active DESC,id DESC')->fetchAll();$orders=$pdo->query("SELECT o.id,o.status,o.total,c.name customer_name,c.address,co.name courier_name FROM orders o JOIN customers c ON c.id=o.customer_id LEFT JOIN couriers co ON co.id=o.courier_id WHERE o.status IN ('ready','out') ORDER BY o.id DESC LIMIT 100")->fetchAll();
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>پیک‌ها</title><link rel="stylesheet" href="assets/style.css"><style>.wrap{max-width:1000px;margin:20px auto;padding:0 12px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:12px}.box{background:#fff;border:1px solid #e5ece6;border-radius:15px;padding:13px;margin:8px 0}.link{direction:ltr;font-family:monospace;font-size:11px;word-break:break-all;background:#f4f6f4;padding:7px;border-radius:8px}@media(max-width:700px){.grid2{grid-template-columns:1fr}}</style></head><body><header class="top"><a class="brand" href="admin.php"><span class="logo">🛵</span><span><b>پیک‌ها و ارسال</b><small>تحویل سفارش و پیگیری پیک</small></span></a><a class="btn pale" href="admin.php">مدیریت اصلی</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="notice"><?=e($err)?></div><?php endif;?><div class="grid2"><section class="panel"><h2>+ پیک جدید</h2><form method="post" class="checkout"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="create"><label>نام<input name="name" required></label><label>موبایل<input name="phone" inputmode="numeric"></label><button class="btn wide">ساخت پیک</button></form><?php foreach($couriers as $co):?><div class="box"><b><?=e($co['name'])?></b> · <?=e($co['phone'])?> <?=$co['active']?'🟢':'🔴'?><div class="link"><?=e('https://websaza.ir/tehran/courier.php?t='.$co['access_token'])?></div><div style="display:flex;gap:6px;margin-top:7px"><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$co['id']?>"><button class="btn pale"><?=$co['active']?'غیرفعال':'فعال'?></button></form><form method="post" onsubmit="return confirm('لینک قبلی پیک از کار بیفتد؟')"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="regen"><input type="hidden" name="id" value="<?=(int)$co['id']?>"><button class="btn pale">لینک جدید</button></form></div></div><?php endforeach;?></section><section class="panel"><h2>سفارش‌های آماده/در مسیر</h2><?php foreach($orders as $o):?><div class="box"><b>#<?=(int)$o['id']?> · <?=e($o['customer_name'])?></b><div class="muted"><?=e($o['address'])?> · <?=number_format((int)$o['total'])?> تومان</div><div class="muted">پیک فعلی: <?=e($o['courier_name']?:'تعیین نشده')?></div><form method="post" style="display:flex;gap:7px;margin-top:8px"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="assign"><input type="hidden" name="order_id" value="<?=(int)$o['id']?>"><select name="courier_id" required><option value="">انتخاب پیک…</option><?php foreach($couriers as $co):if(!$co['active'])continue;?><option value="<?=(int)$co['id']?>"><?=e($co['name'])?></option><?php endforeach;?></select><button class="btn">تحویل به پیک</button></form></div><?php endforeach;?></section></div></main></body></html>
